const args = $input.first().json;
const required = ['nombre', 'telefono', 'ubicacion', 'equipo_o_aplicacion'];
const missing = required.filter(f => !args[f] || String(args[f]).trim() === '');
if (missing.length > 0) {
  return [{ json: { status: 'ERROR', _skip: true, message_to_agent: `Faltó capturar: ${missing.join(', ')}. Pedile al cliente.` } }];
}

// Derive zona desde ubicacion
const ubic = String(args.ubicacion).toLowerCase();
let zona = 'Interior';
if (ubic.includes('caba') || ubic.includes('capital') || ubic.includes('buenos aires capital') || ubic.includes('ciudad de buenos aires')) zona = 'CABA';
else if (ubic.includes('gba') || ubic.includes('gran buenos aires') || ubic.includes('conurbano') || ubic.match(/(zona norte|zona sur|zona oeste)/)) zona = 'GBA';

// Derive linea desde equipo_o_aplicacion o tecnologia_interes
const mapping = {
  'dtf textil': 'DTF Textil', 'dtf uv': 'DTF UV',
  'sublimacion': 'Sublimación', 'sublimación': 'Sublimación',
  'eco-solvente': 'Eco-Solvente', 'ecosolvente': 'Eco-Solvente',
  'solvente': 'Solvente', 'corte': 'Corte', 'sinajet': 'Sinajet',
  'riso': 'RISO', 'konica': 'Konica Minolta IDL',
  'uv': 'UV'
};
const texto = String(args.tecnologia_interes || args.equipo_o_aplicacion || '').toLowerCase();
let linea = null;
for (const [k, v] of Object.entries(mapping)) {
  if (texto.includes(k)) { linea = v; break; }
}

// Build live chat URL — ManyChat dashboard direct link
// PAGE_ID se debe completar con el real de la cuenta ManyChat de SyS
const PAGE_ID = '5013937';
const subscriberId = String(args.subscriber_id || '').trim();
const canal = String(args.canal || '').trim() || 'desconocido';
let liveChatUrl = '';
if (subscriberId && PAGE_ID && !PAGE_ID.startsWith('<<<')) {
  liveChatUrl = `https://app.manychat.com/fb${PAGE_ID}/chat/${subscriberId}`;
}

return [{ json: { ...args, zona_derivada: zona, linea_derivada: linea, canal, subscriber_id: subscriberId, live_chat_url: liveChatUrl } }];

const v = $('Validate Input').first().json;
return [{ json: {
  status: 'RESOLVED',
  data: {
    destino_notificacion_to: 'emarti@sistemasysoluciones.com, marketing@sistemasysoluciones.com',
    destino_notificacion_cc: null,
    canal: v.canal,
    live_chat_url: v.live_chat_url || null,
    mail_enviado: true,
    telegram_enviado: true,
    lead_id: null,
    lead_airtable_url: null
  },
  message_to_agent: 'Lead notificado al equipo comercial (mail + Telegram). Confirmá al cliente que un comercial se va a contactar y cerrá la conversación con calidez.',
  trace_id: $execution.id
} }];
